            "aggregation_key": key,
            "public_inputs": inputs if inputs is not None else ["pi"],
            "proof": body if body is not None else ("blob", pid)}

class Stub(ZKVerifier):
    protocol = "groth16"
    def __init__(self, reject=(), err=(), agg=True):
        self.r=set(reject); self.e=set(err); self.agg=agg
    def aggregate(self, proofs): return ["AGG"]
    def verify_aggregate(self, proofs, a):
        return all(p.proof_id not in self.r and p.proof_id not in self.e for p in proofs) if self.agg else self.agg
    def verify(self, p):
        if p.proof_id in self.e: raise ValueError("x")
        return p.proof_id not in self.r

flaky = Stub(reject={"p2"}, err={"p3"})
q = VerificationQueue(flaky)
